service cloud.firestore {
  match /databases/{database}/documents {
    function isSignedIn() { return request.auth != null; }
    function team(teamId) { return get(/databases/$(database)/documents/teams/$(teamId)).data; }
    function isMember(teamId) { return isSignedIn() && request.auth.uid in team(teamId).members; }
    function isAdmin(teamId) { return isMember(teamId) && team(teamId).members[request.auth.uid].role == 'admin'; }

    match /teams/{teamId} {
