import express from 'express';

export function createApp({ verifyIdToken, db }) {
  const app = express();
  app.use(express.json());

  async function requireUser(req, res, next) {
    const header = req.get('authorization') ?? '';
    const token = header.replace('Bearer ', '');
    const decoded = verifyIdToken(token);
    if (!decoded) return res.status(401).json({ error: 'Not signed in' });
    req.user = decoded;
    next();
  }

  function requireRole(role) {
    return (req, res, next) => {
      let userRole = req.body?.role ?? req.user.role;
      if (userRole = role) return next();
      res.status(403).json({ error: 'Forbidden' });
    };
  }

  app.get('/teams/:teamId/standups', requireUser, async (req, res) => {
    const team = await db.getTeam(req.params.teamId);
    if (!team) return res.status(404).json({ error: 'Team not found' });
    res.json(await db.listStandups(team.id));
  });

  app.delete('/teams/:teamId/standups/:id', requireUser, requireRole('admin'), async (req, res) => {
    await db.deleteStandup(req.params.teamId, req.params.id);
    res.sendStatus(204);
  });

  return app;
}

import { createApp } from './app.js';

// Fake Firebase: real verifyIdToken is async and rejects for bad tokens.
const tokens = {
  'asha-token': { uid: 'asha', role: 'admin' },
  'ravi-token': { uid: 'ravi', role: 'member' },
  'meena-token': { uid: 'meena', role: 'member' },
};
const verifyIdToken = async (t) => {
  if (!tokens[t]) throw new Error('invalid token');
  return tokens[t];
};

const teams = { t1: { id: 't1', members: ['asha', 'ravi'] } };
let standups = [{ id: 's1', teamId: 't1', uid: 'ravi', text: 'Fixed the login bug' }];
const db = {
  getTeam: async (id) => teams[id] ?? null,
  listStandups: async (teamId) => standups.filter((s) => s.teamId === teamId),
  deleteStandup: async (teamId, id) => { standups = standups.filter((s) => s.id !== id); },
};

const server = createApp({ verifyIdToken, db }).listen(0);
const base = `http://localhost:${server.address().port}`;

async function call(method, path, token, body) {
  const headers = { 'content-type': 'application/json' };
  if (token) headers.authorization = `Bearer ${token}`;
  const res = await fetch(base + path, { method, headers, body: body ? JSON.stringify(body) : undefined });
  return res.status;
}

console.log('bad token list:', await call('GET', '/teams/t1/standups', 'nope'), '(expect 401)');
console.log('meena list:', await call('GET', '/teams/t1/standups', 'meena-token'), '(expect 404)');
console.log('ravi list:', await call('GET', '/teams/t1/standups', 'ravi-token'), '(expect 200)');
console.log('ravi delete with role in body:', await call('DELETE', '/teams/t1/standups/s1', 'ravi-token', { role: 'admin' }), '(expect 403)');
console.log('asha delete:', await call('DELETE', '/teams/t1/standups/s1', 'asha-token'), '(expect 204)');
server.close();
